#!/usr/bin/env python3
"""Expand the shared RaBitQ GoAT C template for one ISA."""

from pathlib import Path
import re
import sys

if len(sys.argv) != 3 or sys.argv[1] not in {"avx2", "avx512"}:
    raise SystemExit("usage: expand_kernels.py {avx2|avx512} OUTPUT")

isa = sys.argv[1]
source_dir = Path(__file__).parent


def expand_local_includes(source: str) -> str:
    """Inline local headers so GoAT can discover every entry point."""
    return re.sub(
        r'^#include "([^"]+)"$',
        lambda match: expand_local_includes((source_dir / match.group(1)).read_text()),
        source,
        flags=re.MULTILINE,
    )


source = expand_local_includes((source_dir / "kernels.h").read_text())
source = re.sub(
    r"\n#ifndef RABITQ_FN\n#error RABITQ_FN must be defined[^\n]*\n#endif\n",
    "\n",
    source,
)
source = re.sub(
    r"\n#ifndef RABITQ_SUFFIX\n#error RABITQ_SUFFIX must be defined\n#endif\n"
    r"\n#define RABITQ_CAT_INNER\(a, b\) a##b\n"
    r"#define RABITQ_CAT\(a, b\) RABITQ_CAT_INNER\(a, b\)\n"
    r"#define RABITQ_FN\(name\) RABITQ_CAT\(name, RABITQ_SUFFIX\)\n",
    "\n",
    source,
)
source = re.sub(r"RABITQ_FN\(([^)]+)\)", rf"\1_{isa}", source)
header = (
    "// Code generated by expand_kernels.py from kernels.h. DO NOT EDIT.\n"
    "// The generated file remains a modified derivative of RaBitQ-Library src/simd.\n\n"
    f"#define RABITQ_AVX512 {1 if isa == 'avx512' else 0}\n\n"
)
Path(sys.argv[2]).write_text(header + source)
